import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [socket, setSocket] = useState(null);

  // Récupérer le token
  const getToken = useCallback(() => {
    const token = localStorage.getItem('authToken');
    console.log('🔑 Token récupéré:', token ? 'Présent' : 'Absent');
    return token;
  }, []);

  // Fonction pour nettoyer le token
  const cleanToken = (token) => {
    if (!token) return null;

    let cleanToken = token.trim();

    // Enlever les guillemets
    if (cleanToken.startsWith('"') && cleanToken.endsWith('"')) {
      cleanToken = cleanToken.slice(1, -1);
    }
    if (cleanToken.startsWith("'") && cleanToken.endsWith("'")) {
      cleanToken = cleanToken.slice(1, -1);
    }

    return cleanToken;
  };

  // Axios instance
  const axiosInstance = axios.create({
    baseURL: API_URL,
    timeout: 10000,
  });

  // Ajouter le token à chaque requête
  axiosInstance.interceptors.request.use(
    (config) => {
      const token = getToken();
      if (token) {
        const cleanTokenValue = cleanToken(token);
        config.headers.Authorization = `Bearer ${cleanTokenValue}`;
        console.log('📤 Authorization header ajouté');
      }
      return config;
    },
    (error) => {
      console.error('❌ Erreur intercepteur request:', error);
      return Promise.reject(error);
    }
  );

  // Gérer les erreurs globales
  axiosInstance.interceptors.response.use(
    (response) => response,
    (error) => {
      console.error('❌ Erreur intercepteur response:', {
        status: error.response?.status,
        message: error.response?.data?.message,
        url: error.config?.url
      });

      if (error.response?.status === 401) {
        console.log('🔒 Session expirée, redirection vers login...');
        setError('Session expirée. Veuillez vous reconnecter.');
        localStorage.removeItem('authToken');
        localStorage.removeItem('userData');
        setTimeout(() => {
          window.location.href = '/login';
        }, 1500);
      } else if (error.response?.status === 404) {
        setError('Route non trouvée. Vérifiez l\'URL.');
      } else if (!error.response) {
        setError('Pas de réponse du serveur. Vérifiez que le backend est démarré.');
      }

      return Promise.reject(error);
    }
  );

  // Initialiser Socket.io
  const initializeSocket = useCallback(() => {
    const token = getToken();
    if (!token || socket) return;

    console.log('🔌 Initialisation Socket.io...');

    // Importer dynamiquement socket.io-client
    import('socket.io-client').then(({ io }) => {
      const cleanTokenValue = cleanToken(token);

      const newSocket = io('http://localhost:5000', {
        auth: { token: cleanTokenValue },
        transports: ['websocket', 'polling'],
        reconnection: true,
        reconnectionAttempts: 5,
        reconnectionDelay: 1000,
      });

      newSocket.on('connect', () => {
        console.log('✅ Connecté au serveur Socket.io');
        setError(null);
      });

      newSocket.on('connect_error', (err) => {
        console.error('❌ Erreur connexion Socket.io:', err.message);
        setError('Connexion temps réel indisponible');
      });

      newSocket.on('new_message', (message) => {
        console.log('📨 Nouveau message reçu via socket:', message);

        if (message.conversation_id === currentConversation?.id) {
          setMessages(prev => {
            // Éviter les doublons
            if (prev.some(msg => msg.id === message.id)) {
              return prev;
            }
            return [...prev, message];
          });
        }

        // Mettre à jour la liste des conversations
        setConversations(prev => 
          prev.map(conv => 
            conv.id === message.conversation_id 
              ? { 
                  ...conv, 
                  last_message: message.content,
                  last_message_time: message.created_at,
                  unread_count: conv.unread_count + 1
                }
              : conv
          )
        );
      });

      setSocket(newSocket);
    });
  }, [getToken, socket, currentConversation]);

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      console.log('📡 Récupération des conversations...');

      const response = await axiosInstance.get('/messages/conversations');

      console.log('📊 Réponse conversations:', {
        success: response.data.success,
        count: response.data.conversations?.length
      });

      if (response.data.success) {
        const conversationsData = response.data.conversations || [];
        setConversations(conversationsData);

        if (conversationsData.length > 0 && !currentConversation) {
          // Sélectionner la première conversation par défaut
          setCurrentConversation(conversationsData[0]);
        }
      } else {
        setError(response.data.message || 'Erreur lors du chargement des conversations');
      }
    } catch (err) {
      console.error('❌ Erreur fetchConversations:', err);
      setError(err.response?.data?.message || 'Erreur de connexion au serveur');
    } finally {
      setLoading(false);
    }
  }, [axiosInstance, currentConversation]);

  // Créer ou récupérer une conversation
  const getOrCreateConversation = useCallback(async (adminId) => {
    try {
      setLoading(true);
      setError(null);
      console.log('🆕 Création/récupération conversation avec admin:', adminId);

      // 1. Vérifier si une conversation existe déjà avec cet admin
      const existingConvs = conversations.filter(conv => 
        conv.admin_id === adminId && conv.status !== 'closed'
      );

      if (existingConvs.length > 0) {
        console.log('✅ Conversation existante trouvée');
        const existingConv = existingConvs[0];
        setCurrentConversation(existingConv);
        await fetchMessages(existingConv.id);
        return existingConv;
      }

      // 2. Créer une nouvelle conversation
      const response = await axiosInstance.post('/messages/conversations', {
        admin_id: adminId
      });

      console.log('📊 Réponse création conversation:', response.data);

      if (response.data.success) {
        const newConversation = response.data.conversation;
        setConversations(prev => [newConversation, ...prev]);
        setCurrentConversation(newConversation);
        setMessages([]); // Réinitialiser les messages pour la nouvelle conversation

        return newConversation;
      } else {
        setError(response.data.message || 'Erreur lors de la création de la conversation');
        return null;
      }
    } catch (err) {
      console.error('❌ Erreur getOrCreateConversation:', err);
      setError(err.response?.data?.message || 'Erreur serveur');
      return null;
    } finally {
      setLoading(false);
    }
  }, [axiosInstance, conversations, fetchMessages]);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      setLoading(true);
      setError(null);
      console.log(`📨 Chargement messages conversation ${conversationId}...`);

      const response = await axiosInstance.get(`/messages/conversations/${conversationId}/messages`);

      console.log('📊 Réponse messages:', {
        success: response.data.success,
        count: response.data.messages?.length,
        conversation: response.data.conversation?.id
      });

      if (response.data.success) {
        const messagesData = response.data.messages || [];
        const conversationData = response.data.conversation;

        setMessages(messagesData);
        setCurrentConversation(conversationData);

        // Mettre à jour la conversation dans la liste
        setConversations(prev => 
          prev.map(conv => 
            conv.id === conversationId 
              ? { ...conv, ...conversationData }
              : conv
          )
        );
      } else {
        setError(response.data.message || 'Erreur lors du chargement des messages');
      }
    } catch (err) {
      console.error('❌ Erreur fetchMessages:', err);
      setError(err.response?.data?.message || 'Erreur de connexion au serveur');
    } finally {
      setLoading(false);
    }
  }, [axiosInstance]);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    if (!content || content.trim() === '') {
      setError('Le contenu du message est requis');
      throw new Error('Le contenu du message est requis');
    }

    try {
      console.log(`📤 Envoi message conversation ${conversationId}:`, content);

      const response = await axiosInstance.post('/messages/messages', {
        conversation_id: conversationId,
        content: content.trim()
      });

      console.log('📊 Réponse envoi message:', response.data);

      if (response.data.success) {
        const newMessage = response.data.message;

        // Ajouter le message localement
        setMessages(prev => [...prev, newMessage]);

        // Mettre à jour la conversation
        setCurrentConversation(prev => ({
          ...prev,
          last_message: newMessage.content,
          last_message_time: newMessage.created_at
        }));

        // Mettre à jour la liste des conversations
        setConversations(prev => 
          prev.map(conv => 
            conv.id === conversationId 
              ? { 
                  ...conv, 
                  last_message: newMessage.content,
                  last_message_time: newMessage.created_at
                }
              : conv
          )
        );

        // Envoyer via socket si disponible
        if (socket && socket.connected) {
          socket.emit('send_message', {
            conversationId: conversationId,
            message: newMessage
          });
        }

        return newMessage;
      } else {
        setError(response.data.message || 'Erreur lors de l\'envoi du message');
        throw new Error(response.data.message);
      }
    } catch (err) {
      console.error('❌ Erreur sendMessage:', err);
      setError(err.response?.data?.message || 'Erreur lors de l\'envoi du message');
      throw err;
    }
  }, [axiosInstance, socket]);

  // Récupérer tous les admins
  const fetchAdmins = useCallback(async () => {
    try {
      console.log('👑 Récupération des admins...');
      const response = await axiosInstance.get('/users/admins');

      if (response.data.success) {
        return response.data.admins || [];
      } else {
        setError(response.data.message || 'Erreur lors du chargement des admins');
        return [];
      }
    } catch (err) {
      console.error('❌ Erreur fetchAdmins:', err);
      setError('Erreur lors du chargement des admins');
      return [];
    }
  }, [axiosInstance]);

  // Récupérer les admins disponibles (avec moins de conversations)
  const fetchAvailableAdmins = useCallback(async () => {
    try {
      console.log('👑 Récupération des admins disponibles...');
      const response = await axiosInstance.get('/messages/admins/available');

      if (response.data.success) {
        return response.data.admins || [];
      } else {
        setError(response.data.message || 'Erreur lors du chargement des admins disponibles');
        return [];
      }
    } catch (err) {
      console.error('❌ Erreur fetchAvailableAdmins:', err);
      setError('Erreur lors du chargement des admins disponibles');
      return [];
    }
  }, [axiosInstance]);

  // Marquer les messages comme lus
  const markAsRead = useCallback(async (conversationId) => {
    try {
      await axiosInstance.post('/messages/messages/mark-read', {
        conversation_id: conversationId
      });

      // Mettre à jour localement
      setConversations(prev => 
        prev.map(conv => 
          conv.id === conversationId 
            ? { ...conv, unread_count: 0 }
            : conv
        )
      );

      setMessages(prev => 
        prev.map(msg => ({ ...msg, is_read: true }))
      );
    } catch (err) {
      console.error('Erreur markAsRead:', err);
    }
  }, [axiosInstance]);

  // Obtenir le nombre de messages non lus
  const getUnreadCount = useCallback(async () => {
    try {
      const response = await axiosInstance.get('/messages/unread-count');
      if (response.data.success) {
        return response.data.unread_count || 0;
      }
      return 0;
    } catch (err) {
      console.error('Erreur getUnreadCount:', err);
      return 0;
    }
  }, [axiosInstance]);

  // Initialisation au montage
  useEffect(() => {
    const token = getToken();
    if (token) {
      initializeSocket();
      fetchConversations();
    } else {
      setError('Vous devez vous connecter pour accéder aux messages');
    }

    // Nettoyage
    return () => {
      if (socket) {
        socket.disconnect();
      }
    };
  }, [getToken, initializeSocket, fetchConversations]);

  return {
    // États
    conversations,
    messages,
    currentConversation,
    loading,
    error,

    // Méthodes
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAdmins,
    fetchAvailableAdmins,
    markAsRead,
    getUnreadCount,

    // Setters pour mise à jour manuelle
    setError,
    setMessages,
    setCurrentConversation,
    setConversations
  };
};

export default useMessages;
